"use client";
import React, { useEffect, useState } from "react";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {
  faFan,
  faHandsHoldingCircle,
  faLeaf,
  faPaw,
} from "@fortawesome/free-solid-svg-icons";
import Destinations from "../../after-your-booking/destinations";

const tabs = [
  { id: "accountable", label: "What defines an accountable operator?" },
  { id: "cards", label: "Eco-friendly Cards" },
  { id: "types", label: "Adventure Types" },
  { id: "actions", label: "Operator Actions" },
];

const ecoCards = [
  {
    icon: faFan,
    title: "Minimizing Carbon Footprint",
    body: "These operators are actively working to reduce their carbon footprint through initiatives like carbon offsetting, neutrality programs, and the use of electric transportation, all aimed at achieving net-zero emissions by 2050.",
  },
  {
    icon: faHandsHoldingCircle,
    title: "Empowering Destinations",
    body: "These operators focus on supporting the communities that make their adventures possible, through efforts like backing locally-owned businesses, employing local guides, and promoting local accommodations.",
  },
  {
    icon: faPaw,
    title: "Ethical Treatment of Animals",
    body: "These operators have animal welfare policies that prevent exploitative practices like elephant riding and animal entertainment, ensuring the protection of wildlife and the preservation of natural habitats.",
  },
  {
    icon: faLeaf,
    title: "Eco-friendly Initiatives",
    body: "These operators reduce the impact of travel on local communities and the environment by focusing on long-term sustainability. Travelers can look forward to educational experiences that encourage responsible tourism.",
  },
];

const adventureTypes = [
  {
    title: "Nature Walks & Expeditions",
    image: "/images/hiking.webp",
    href: "/search?term=hiking",
    cta: "Hiking Adventures",
    body: (
      <>
        By carefully navigating established trails, supporting local
        communities, reducing your carbon footprint, and offering educational
        opportunities, a hiking adventure is one of our most eco-conscious
        Adventure Styles.{" "}
        <b className="tw-text-[#14101c]">
          It allows you to immerse yourself in nature&apos;s beauty while
          encouraging responsible travel practices.
        </b>
      </>
    ),
  },
  {
    title: "Biking",
    image: "/images/cycling.jpg",
    href: "/search?term=biking",
    cta: "Biking Adventures",
    body: "Cycling isn't just an eco-friendly, carbon-free way to travel; it also allows you to connect with local culture and support nearby businesses. With the added bonus of physical activity and the thrill of an organized adventure, cycling provides an experience that's both rewarding for you and the planet.",
  },
  {
    title: "Cultural Immersion",
    image: "/images/culture.jpg",
    href: "/search?term=culture",
    cta: "Cultural Immersion Adventures",
    body: "Immerse yourself in the world's rich cultural heritage. Experience authentic traditions, support local communities, and stay in locally-owned accommodations. Embark on an adventure that honors and helps preserve the beauty of our shared cultural legacy.",
  },
];

const ActionOperators = () => {
  const [active, setActive] = useState(tabs[0].id);

  useEffect(() => {
    const sections = tabs
      .map((t) => document.getElementById(t.id))
      .filter((el): el is HTMLElement => el !== null);

    const observer = new IntersectionObserver(
      (entries) => {
        const visible = entries
          .filter((e) => e.isIntersecting)
          .sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0];
        if (visible) setActive(visible.target.id);
      },
      { rootMargin: "-40% 0px -55% 0px", threshold: [0, 0.25, 0.5, 1] },
    );

    sections.forEach((s) => observer.observe(s));
    return () => observer.disconnect();
  }, []);

  return (
    <main className="tw-font-display tw-bg-white">
      {/* Hero */}
      <section className="tw-relative tw-overflow-hidden">
        <div
          className="tw-absolute tw-inset-0 tw-bg-cover tw-bg-center"
          style={{ backgroundImage: "url('/images/naturebanner1.jpg')" }}
          aria-hidden="true"
        />
        <div
          className="tw-absolute tw-inset-0"
          style={{
            background:
              "linear-gradient(180deg, rgba(20,16,28,0.45) 0%, rgba(20,16,28,0.55) 55%, rgba(20,16,28,0.8) 100%)",
          }}
          aria-hidden="true"
        />
        <div className="tw-relative tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10 tw-py-24 md:tw-py-32">
          <div className="tw-max-w-[760px]">
            <span className="tw-inline-flex tw-items-center tw-gap-2 tw-rounded-full tw-bg-white/10 tw-border tw-border-solid tw-border-white/20 tw-px-4 tw-py-1.5 tw-text-[13px] tw-font-semibold tw-text-white tw-backdrop-blur">
              Operator Actions
            </span>
            <h1 className="tw-mt-5 tw-text-[clamp(32px,5vw,56px)] tw-font-bold tw-tracking-tight tw-leading-[1.05] tw-text-white tw-m-0">
              Accountable Adventure Guides
            </h1>
            <p className="tw-mt-5 tw-mb-0 tw-text-[17px] tw-leading-[1.6] tw-text-white/85 tw-max-w-[60ch]">
              Over 2,500 adventure operators, united by a shared passion for
              sustainable travel and a positive impact on the planet.
            </p>
          </div>
        </div>
      </section>

      {/* Sticky tab nav */}
      <div className="tw-sticky tw-top-0 tw-z-30 tw-bg-white/90 tw-backdrop-blur tw-border-0 tw-border-b tw-border-solid tw-border-[#ebe7f0]">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-4 md:tw-px-8">
          <nav
            className="tw-flex tw-gap-1.5 tw-overflow-x-auto tw-py-3"
            style={{ scrollbarWidth: "none" }}
          >
            {tabs.map((tab) => (
              <a
                key={tab.id}
                href={`#${tab.id}`}
                aria-current={active === tab.id ? "true" : undefined}
                className={`tw-whitespace-nowrap tw-rounded-full tw-px-4 tw-py-2 tw-text-[14px] tw-font-semibold tw-no-underline tw-transition-colors ${
                  active === tab.id
                    ? "tw-bg-[#854ec9] tw-text-white"
                    : "tw-text-[#5d556c] hover:tw-bg-[#faf9fc] hover:tw-text-[#14101c]"
                }`}
              >
                {tab.label}
              </a>
            ))}
          </nav>
        </div>
      </div>

      {/* Intro */}
      <section className="tw-py-12 md:tw-py-16">
        <div className="tw-container tw-mx-auto tw-max-w-[820px] tw-px-6 md:tw-px-8 lg:tw-px-10 tw-text-center">
          <h2 className="tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
            Over 2,500 Operators, United by a Common Goal
          </h2>
          <p className="tw-mt-5 tw-mb-0 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
            At TravelShop Booking, we&apos;re excited to collaborate with over
            2,500 adventure operators, all united by a shared passion for
            sustainable travel. Each operator brings their own sustainability
            efforts to the table, offering countless opportunities to make a
            positive impact. By highlighting our partners&apos; initiatives and
            engaging our customers, we aim to play a key role in preserving our
            planet and its stunning destinations for future generations.
          </p>
        </div>
      </section>

      {/* Responsible travel */}
      <section className="tw-pb-12 md:tw-pb-16">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-grid tw-grid-cols-1 lg:tw-grid-cols-2 tw-gap-10 lg:tw-gap-14 tw-items-center">
            <div>
              <img
                src="/images/adventuregirl.jpg"
                alt="Adventurer"
                loading="lazy"
                className="tw-w-full tw-rounded-2xl tw-object-cover tw-shadow-xl tw-shadow-[#14101c]/10"
              />
            </div>
            <div>
              <h3 className="tw-text-[clamp(22px,2.6vw,28px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
                What does responsible travel mean?
              </h3>
              <p className="tw-mt-4 tw-mb-0 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
                Imagine traveling the world and making a positive difference for
                the planet and its communities. That&apos;s what sustainable
                tourism is all about — a travel approach that considers the
                environmental, social, and economic effects of tourism, making
                thoughtful adjustments to reduce harmful impacts. It focuses on
                supporting local communities, businesses, and nature, ensuring
                the future of travel for generations to come.
              </p>
            </div>
          </div>
        </div>
      </section>

      {/* Quote band */}
      <section className="tw-py-12 md:tw-py-16 tw-bg-[#faf9fc]">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-grid tw-grid-cols-1 lg:tw-grid-cols-2 tw-gap-10 lg:tw-gap-14 tw-items-center">
            <p className="tw-order-2 lg:tw-order-1 tw-m-0 tw-text-[clamp(22px,3vw,32px)] tw-font-bold tw-leading-[1.25] tw-tracking-tight tw-text-[#14101c]">
              Being a responsible operator goes beyond offering amazing travel
              experiences — it&apos;s about{" "}
              <span className="tw-text-[#854ec9]">
                making a positive difference in the world.
              </span>
            </p>
            <div className="tw-order-1 lg:tw-order-2">
              <img
                src="/images/african.jpg"
                alt="Local community"
                loading="lazy"
                className="tw-w-full tw-rounded-2xl tw-object-cover tw-shadow-xl tw-shadow-[#14101c]/10"
              />
            </div>
          </div>
        </div>
      </section>

      {/* Accountable */}
      <section
        id="accountable"
        className="tw-scroll-mt-20 tw-py-12 md:tw-py-16"
      >
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-grid tw-grid-cols-1 lg:tw-grid-cols-2 tw-gap-10 lg:tw-gap-14 tw-items-center">
            <div className="tw-order-2 lg:tw-order-1">
              <img
                src="/images/natives.jpg"
                alt="Local culture"
                loading="lazy"
                className="tw-w-full tw-rounded-2xl tw-object-cover tw-shadow-xl tw-shadow-[#14101c]/10"
              />
            </div>
            <div className="tw-order-1 lg:tw-order-2">
              <h3 className="tw-text-[clamp(22px,2.6vw,28px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
                What qualities define an accountable operator?
              </h3>
              <p className="tw-mt-4 tw-mb-0 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
                Being a responsible operator is about more than delivering
                exceptional travel experiences — it&apos;s about making a
                meaningful impact on the world. It&apos;s about crafting lasting
                memories for travelers while protecting the beauty of the places
                we visit, engaging with local communities, supporting their
                economies, and fostering respect for the environment and
                cultural heritage.
              </p>
            </div>
          </div>
        </div>
      </section>

      {/* Eco cards */}
      <section
        id="cards"
        className="tw-scroll-mt-20 tw-py-12 md:tw-py-16 tw-bg-[#faf9fc]"
      >
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-max-w-[760px] tw-mb-10">
            <h2 className="tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
              How to identify a responsible operator
            </h2>
            <p className="tw-mt-4 tw-mb-0 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
              Our commitment shines through our innovative Sustainability Cards,
              making it easy to choose adventures that align with your values —
              operators with initiatives to reduce carbon emissions, animal
              welfare guidelines, local leadership, and support for community
              development and environmental projects.
            </p>
          </div>
          <div className="tw-grid tw-grid-cols-1 sm:tw-grid-cols-2 lg:tw-grid-cols-4 tw-gap-5 lg:tw-gap-6">
            {ecoCards.map((card) => (
              <div
                key={card.title}
                className="tw-rounded-2xl tw-bg-white tw-border tw-border-solid tw-border-[#ebe7f0] tw-p-6 hover:tw-border-[#d8d2e1] hover:tw-shadow-lg tw-transition-all tw-duration-200"
              >
                <div className="tw-flex tw-h-14 tw-w-14 tw-items-center tw-justify-center tw-rounded-2xl tw-bg-[#854ec9]/10 tw-text-[#854ec9]">
                  <FontAwesomeIcon icon={card.icon} className="tw-text-2xl" />
                </div>
                <h3 className="tw-mt-4 tw-text-[17px] tw-font-bold tw-text-[#14101c] tw-m-0">
                  {card.title}
                </h3>
                <p className="tw-mt-2 tw-mb-0 tw-text-[14px] tw-leading-[1.6] tw-text-[#5d556c]">
                  {card.body}
                </p>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Adventure types */}
      <section id="types" className="tw-scroll-mt-20 tw-py-12 md:tw-py-16">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-max-w-[820px] tw-mb-10">
            <h2 className="tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
              Eco-friendly Adventure Types
            </h2>
            <p className="tw-mt-4 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
              Sustainable adventures go beyond surface-level exploration,
              leaving a positive impact and spending more time in the
              destination.{" "}
              <b className="tw-text-[#14101c]">
                By choosing a sustainable adventure, you directly contribute to
                the United Nations Sustainable Development Goals of No Poverty
                and Climate Action.
              </b>
            </p>
          </div>
          <div className="tw-grid tw-grid-cols-1 md:tw-grid-cols-3 tw-gap-5 lg:tw-gap-6">
            {adventureTypes.map((card) => (
              <div
                key={card.title}
                className="tw-flex tw-flex-col tw-overflow-hidden tw-rounded-2xl tw-bg-white tw-border tw-border-solid tw-border-[#ebe7f0] hover:tw-shadow-lg tw-transition-shadow tw-duration-200"
              >
                <img
                  src={card.image}
                  alt={card.title}
                  loading="lazy"
                  className="tw-h-48 tw-w-full tw-object-cover"
                />
                <div className="tw-flex tw-flex-col tw-flex-1 tw-p-6">
                  <h3 className="tw-text-[18px] tw-font-bold tw-text-[#14101c] tw-m-0">
                    {card.title}
                  </h3>
                  <p className="tw-mt-2 tw-mb-0 tw-text-[14px] tw-leading-[1.6] tw-text-[#5d556c]">
                    {card.body}
                  </p>
                  <a
                    href={card.href}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="tw-mt-4 tw-inline-flex tw-items-center tw-gap-2 tw-self-start tw-bg-[#854ec9] hover:tw-bg-[#6a3da4] tw-text-white tw-font-semibold tw-text-[14px] tw-px-5 tw-py-2.5 tw-rounded-full tw-no-underline tw-transition-colors"
                  >
                    {card.cta} <span aria-hidden="true">→</span>
                  </a>
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Featured banner */}
      <section className="tw-pb-12 md:tw-pb-16">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-relative tw-overflow-hidden tw-rounded-3xl tw-min-h-[260px] tw-flex tw-items-center tw-justify-center">
            <img
              src="/images/kayak1.jpg"
              alt="Kayaking"
              loading="lazy"
              className="tw-absolute tw-inset-0 tw-h-full tw-w-full tw-object-cover"
            />
            <div
              className="tw-absolute tw-inset-0"
              style={{ background: "rgba(20,16,28,0.5)" }}
              aria-hidden="true"
            />
            <h2 className="tw-relative tw-max-w-[720px] tw-px-6 tw-text-center tw-text-[clamp(22px,3.2vw,34px)] tw-font-bold tw-tracking-tight tw-text-white tw-m-0">
              Planned Adventures are the most eco-friendly way to explore
            </h2>
          </div>
        </div>
      </section>

      {/* Actions */}
      <section id="actions" className="tw-scroll-mt-20 tw-pb-12 md:tw-pb-16">
        <div className="tw-container tw-mx-auto tw-max-w-[820px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <h2 className="tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
            Spotlighting Operators Making a Positive Impact
          </h2>
          <p className="tw-mt-4 tw-mb-0 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
            We regularly update our operator pages to highlight the inspiring
            and innovative initiatives our operators around the world are
            implementing. As part of our commitment to sustainability, we
            prioritize operators making a positive impact by featuring them in
            our communications, emails, and search results.
          </p>
        </div>
      </section>

      <Destinations />
    </main>
  );
};

export default ActionOperators;
